from pysat.solvers import Solver
from pysat.formula import CNF

# Variables: x[i][j] = 1 means pigeon i is assigned to hole j
# Pigeons: 0..3 (4 pigeons), Holes: 0..2 (3 holes)

num_pigeons = 4
num_holes = 3

# Variable encoding: var(i, j) = i * num_holes + j + 1
def var(i, j):
    return i * num_holes + j + 1

cnf = CNF()

# Constraint 1: Each pigeon must be in AT LEAST one hole
for i in range(num_pigeons):
    cnf.append([var(i, j) for j in range(num_holes)])

# Constraint 2: Each pigeon must be in AT MOST one hole
for i in range(num_pigeons):
    for j1 in range(num_holes):
        for j2 in range(j1 + 1, num_holes):
            cnf.append([-var(i, j1), -var(i, j2)])

# Constraint 3: Each hole contains AT MOST one pigeon
for j in range(num_holes):
    for i1 in range(num_pigeons):
        for i2 in range(i1 + 1, num_pigeons):
            cnf.append([-var(i1, j), -var(i2, j)])

solver = Solver(name='cd')
solver.append_formula(cnf)
result = solver.solve()

print(f"Satisfiable: {result}")
if result:
    model = solver.get_model()
    assignment = [-1] * num_pigeons
    for i in range(num_pigeons):
        for j in range(num_holes):
            if var(i, j) in model:
                assignment[i] = j
    print(f"Assignment: {assignment}")
else:
    print("UNSATISFIABLE — No valid assignment exists.")
    print("\nReason: Pigeonhole Principle — you cannot place 4 pigeons")
    print("into 3 holes with each hole holding at most 1 pigeon.")
    print(f"  Pigeons: {num_pigeons}, Holes: {num_holes}")
    print(f"  Need at least {num_pigeons} holes for {num_pigeons} pigeons.")
